<script module lang="ts">
/**
 * A key number with its label and direction of change (`design/components/stat.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stat.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot, type IconRole } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/stat.module.css'
import Badge from './Badge.svelte'
import Skeleton from './Skeleton.svelte'
import Sparkline from '../charts/Sparkline.svelte'

export type DeltaDirection = 'up' | 'down'

export interface StatDelta {
  value: string
  direction: DeltaDirection
  positive?: boolean
}

export interface StatTrend {
  direction: DeltaDirection
  label: string
}

export interface StatFooter {
  primary: string
  secondary: string
}

export interface StatProps {
  delta?: StatDelta
  /**
   * Shown when there is no delta, such as "vs last week".
   */
  description?: string
  /**
   * The two-line footer: the interpretation, then the period it covers.
   */
  footer?: StatFooter
  icon?: IconRole
  label: string
  /**
   * The number has not arrived. The label row stays, and the value and each part the caller
   * passes that states the number is a Skeleton of that part's size. `value` stays required, as
   * a chart's rows do with its `loading`: pass what there is, `''` or the last value, and it is
   * not drawn.
   */
  loading?: boolean
  /**
   * What a screen reader hears in the value's place while `loading`, the value's Skeleton's
   * name. Default "Loading".
   */
  loadingLabel?: string
  /**
   * Tabular figures, so a column of these lines up.
   */
  numeric?: boolean
  /**
   * The trend as a shape: a `Sparkline` at the value row's inline end. It can sit beside `trend`
   * (words for the direction, a shape for the path) and replaces neither `delta` nor `footer`.
   * `Sparkline` draws it, and renders nothing for fewer than two points.
   */
  spark?: readonly number[]
  /**
   * The sparkline's accessible name, as a function of the stat's label because the wording
   * belongs to the catalog; the default is `{label}, recent trend`.
   */
  sparkLabel?: (label: string) => string
  /**
   * The neutral movement chip, top-right. See `StatTrend` for why it is not `delta`.
   */
  trend?: StatTrend
  /**
   * Already formatted by the app.
   */
  value: string
}
</script>

<script lang="ts">
let {
  delta,
  description,
  footer,
  icon,
  label: labelOwn,
  loading = false,
  loadingLabel = 'Loading',
  numeric = true,
  spark,
  sparkLabel = (label: string) => `${label}, recent trend`,
  trend,
  value,
}: StatProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const positive = $derived(
  delta === undefined ? undefined : (delta.positive ?? delta.direction === 'up'),
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.stat}
    data-member="stat"
    data-loading={(loading) ? '' : undefined}
    aria-busy={(loading) ? true : undefined}
    ><div class={styles.labelRow}
      ><span class={styles.label}>{label}</span
      >{#if icon !== undefined || trend !== undefined
        }<span class={styles.labelEnd}
          >{#if icon !== undefined}<span class={styles.glyph}><Icon name={icon} /></span>{/if
          }{#if trend !== undefined && loading
            }<span class={styles.trendPlaceholder}><Skeleton textStep="xs" width={7} /></span
          >{:else if trend !== undefined
            }<Badge variant="outline" icon={trend.direction}>{trend.label}</Badge
          >{/if
        }</span
      >{/if
    }</div
    ><div class={styles.valueRow}
      >{#if loading
        }<Skeleton textStep="3xl" width={10} label={loadingLabel}
      />{:else
        }<span class={styles.value} data-numeric={(numeric) ? '' : undefined}>{value}</span
      >{/if
      }{#if spark !== undefined
        }<span class={styles.spark}
          >{#if loading
            }<Skeleton shape="rect" size={6} width={9}
          />{:else
            }<Sparkline data={spark} label={sparkLabel(label)}
          />{/if
        }</span
      >{/if
    }</div
    >{#if delta !== undefined && loading
      }<Skeleton textStep="sm" width={9}
    />{:else if delta !== undefined
      }<span
        class={styles.delta}
        data-direction={delta.direction}
        data-positive={(positive) ? '' : undefined}
        ><Icon name={delta.direction} size="sm"
        /><span aria-hidden="true">{delta.value}</span
        ><span class={styles.spoken}
          >{`${delta.direction} ${delta.value} — ${positive ? 'positive' : 'negative'}`
        }</span
      ></span
    >{:else if description !== undefined && loading
      }<Skeleton textStep="xs" width={10}
    />{:else if description !== undefined
      }<span class={styles.description}>{description}</span
    >{/if
    }{#if footer !== undefined
      }<div class={styles.footer}
        >{#if loading
          }<Skeleton textStep="sm"
          /><Skeleton textStep="sm" width={10}
        />{:else
          }<span class={styles.footerPrimary}
            >{footer.primary
            }{#if trend !== undefined
              }<span class={styles.footerGlyph}><Icon name={trend.direction} size="sm" /></span
            >{/if
          }</span
          ><span class={styles.footerSecondary}>{footer.secondary}</span
        >{/if
      }</div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
